let next=0,owner=null,aToken=null,bToken=null,maxAccepted=0,value='initial',log=[];
const show=()=>world.textContent='Lease owner: '+(owner||'none')+'
A token: '+(aToken??'none')+'; B token: '+(bToken??'none')+'
Resource max accepted: '+maxAccepted+'
Resource value: '+value+'

'+log.join('
');
const write=(who,token,val)=>{if(token===null){log.push(who+' has no token');return}if(fencing.checked&&token<maxAccepted){log.push('REJECT '+who+' token '+token+' < '+maxAccepted);return}maxAccepted=Math.max(maxAccepted,token);value=val;log.push('ACCEPT '+who+' token '+token)};
grantA.onclick=()=>{aToken=++next;owner='A';log.push('A granted token '+aToken);show()};expireA.onclick=()=>{if(owner==='A')owner=null;log.push('A lease expired; A process may still resume');show()};grantB.onclick=()=>{bToken=++next;owner='B';log.push('B granted token '+bToken);show()};writeB.onclick=()=>{write('B',bToken,'snapshot-B');show()};resumeA.onclick=()=>{write('A',aToken,'stale-snapshot-A');show()};reset.onclick=()=>{next=0;owner=null;aToken=null;bToken=null;maxAccepted=0;value='initial';log=[];show()};fencing.oninput=show;show();
